  IF EXISTS (
    SELECT 1 FROM regulatory_data.evidence_sources
    WHERE source_title = 'IGR Guidance Values — Gandhinagara SRO (Karnataka Gazette 30-Sep-2023)'
      AND org_id IS NULL
